CREATE POLICY "Admins can create orders" ON public.orders FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can delete orders" ON public.orders FOR DELETE TO authenticated USING (has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can create order items" ON public.order_items FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), 'admin'::app_role));